// Combinar datos del cliente y resultados de búsqueda

const preproceso = $('1. Pre-procesamiento YCloud').first().json;
const cliente = $('2. Obtener Cliente').first().json;

// Obtener productos de búsqueda (puede venir vacío)
let productosEncontrados = [];
try {
  const busquedaItems = $('3. Búsqueda Automática Productos').all();
  productosEncontrados = busquedaItems.map(item => item.json);
} catch (e) {
  productosEncontrados = [];
}

// Formatear productos para el prompt
let productosTexto = '';
if (productosEncontrados.length > 0) {
  productosTexto = productosEncontrados.map((p, i) => 
    `${i+1}. ${p.name} - $${Number(p.price).toLocaleString('es-CO')} (${p.category_name})`
  ).join('\n');
} else if (preproceso.esIntentoBusqueda) {
  productosTexto = `❌ No se encontraron productos para: "${preproceso.terminoBusqueda}"`;
} else {
  productosTexto = '(No se realizó búsqueda de productos)';
}

// ========== CONTEXTO DE TIEMPO ==========
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Dom, 1=Lun, 2=Mar, etc.
const hour = now.getHours();
const pasoCutoff = hour >= 10;

// Calcular días hasta próxima entrega
let diasHastaEntrega;
let mensajeEntrega;

switch(dayOfWeek) {
  case 0: // Domingo
    diasHastaEntrega = 2;
    mensajeEntrega = "Próxima entrega: Martes";
    break;
  case 1: // Lunes
    diasHastaEntrega = 1;
    mensajeEntrega = "Próxima entrega: Martes";
    break;
  case 2: // Martes
    if (pasoCutoff) {
      diasHastaEntrega = 3;
      mensajeEntrega = "Ya pasaron las 10AM. Próxima entrega: Viernes";
    } else {
      diasHastaEntrega = 0;
      mensajeEntrega = "¡Ordena antes de las 10AM para recibir HOY!";
    }
    break;
  case 3: // Miércoles
    diasHastaEntrega = 2;
    mensajeEntrega = "Próxima entrega: Viernes";
    break;
  case 4: // Jueves
    diasHastaEntrega = 1;
    mensajeEntrega = "Próxima entrega: Viernes";
    break;
  case 5: // Viernes
    if (pasoCutoff) {
      diasHastaEntrega = 4;
      mensajeEntrega = "Ya pasaron las 10AM. Próxima entrega: Martes";
    } else {
      diasHastaEntrega = 0;
      mensajeEntrega = "¡Ordena antes de las 10AM para recibir HOY!";
    }
    break;
  case 6: // Sábado
    diasHastaEntrega = 3;
    mensajeEntrega = "Próxima entrega: Martes";
    break;
  default:
    diasHastaEntrega = 1;
    mensajeEntrega = "Próxima entrega: Martes o Viernes";
}

// Calcular fecha de entrega
const fechaEntrega = new Date(now);
fechaEntrega.setDate(now.getDate() + diasHastaEntrega);

const proximaEntrega = fechaEntrega.toLocaleDateString('es-CO', { 
  weekday: 'long', 
  day: 'numeric', 
  month: 'long' 
});

const fechaActual = now.toLocaleDateString('es-CO', { 
  weekday: 'long', 
  day: 'numeric', 
  month: 'long',
  year: 'numeric'
});

const horaActual = now.toLocaleTimeString('es-CO', { 
  hour: '2-digit', 
  minute: '2-digit',
  hour12: true
});

return {
  json: {
    // Datos del cliente
    clienteId: cliente.id,
    clienteTelefono: cliente.telefono,
    clienteNombre: cliente.nombre || 'No registrado',
    clienteEstado: cliente.estado_conversacion,
    clienteDireccion: cliente.direccion || '',
    clienteCarrito: cliente.pre_pedido || [],
    clienteTotalPedidos: cliente.total_pedidos || 0,

    // Datos del mensaje
    mensajeCliente: preproceso.messageText,
    terminoBusqueda: preproceso.terminoBusqueda,
    esIntentoBusqueda: preproceso.esIntentoBusqueda,

    // Productos encontrados
    productosEncontrados,
    productosTexto,

    // Contexto de comunicación
    from: preproceso.from,
    to: preproceso.to,
    saludo: preproceso.saludo,

    // ========== CONTEXTO DE TIEMPO (NUEVO) ==========
    fechaActual: fechaActual,
    horaActual: horaActual,
    horaNumero: hour,
    diaNumero: dayOfWeek,
    pasoCutoff: pasoCutoff,
    proximaEntrega: proximaEntrega,
    mensajeEntrega: mensajeEntrega,
    diasHastaEntrega: diasHastaEntrega
  }
};

