SELECT 
  COALESCE(
    (SELECT SUM((item->>'precio')::numeric * COALESCE((item->>'cantidad')::int, 1))
     FROM clientes, jsonb_array_elements(pre_pedido) AS item
     WHERE telefono = '{{ $('1. Pre-procesamiento YCloud').first().json.from }}'
    ), 0
  ) as total,
  pre_pedido as items
FROM clientes
WHERE telefono = '{{ $('1. Pre-procesamiento YCloud').item.json.from }}';

