// Obtener el producto de la consulta
const producto = $input.first().json;
// Obtener el contexto del preprocesamiento
const contexto = $('1. Pre-procesamiento YCloud').first().json;
// Formatear producto al formato esperado
const productoFormateado = {
  producto_id: producto.id,
  producto_nombre: producto.name,
  name: producto.name,
  id: producto.id,
  precio: producto.price,
  price: producto.price,
  main_image_url: producto.main_image_url,
  description: producto.description,
  category: producto.category,
  stock: producto.stock
};
// Retornar contexto con el producto encontrado
return {
  json: {
    ...contexto,
    productosEncontrados: [productoFormateado],
    productosTexto: `Producto del botón: ${producto.name} - $${Number(producto.price).toLocaleString('es-CO')}`
  }
};
